/**
 * @description TEMPLATE payload class (event Payload Source = Apex Class). Rename it, change the query and the JSON
 * keys to the other system's contract, then type the class name in the event's Payload Class field. Integration Hub
 * calls build() once per send with every record Id, and adds the transaction Id key (sfTransactionId by default) to
 * each body.
 * @group Integration Hub
 */
public with sharing class IH_SamplePayloadBuilder implements IntegrationHub.IPayloadBuilder {

    /**
     * @description One body per record.
     * @param req the event key, the related object and the record Ids of this send
     * @return the body per record Id; a record without a body is not sent
     */
    public Map<Id, Object> build(IntegrationHub.PayloadRequest req) {
        Map<Id, Object> bodies = new Map<Id, Object>();
        if (req == null || req.recordIds == null || req.recordIds.isEmpty()) {
            return bodies;
        }
        for (Case c : new Elevated().records(new Set<Id>(req.recordIds))) {
            bodies.put(c.Id, body(c));
        }
        return bodies;
    }

    /**
     * @description The JSON of one record. Change the keys and values to the other system's contract.
     * @param c the record
     * @return the body
     */
    @TestVisible
    private static Map<String, Object> body(Case c) {
        return new Map<String, Object>{
            'caseNumber' => c.CaseNumber,
            'title' => c.Subject,
            'status' => c.Status,
            'customer' => new Map<String, Object>{ 'accountId' => c.AccountId, 'name' => c.Account?.Name }
        };
    }

    /**
     * @description Reads the records in system mode, so the payload does not depend on the sending user's access.
     */
    private without sharing class Elevated {

        List<Case> records(Set<Id> recordIds) {
            return [SELECT Id, CaseNumber, Subject, Status, AccountId, Account.Name
                FROM Case WHERE Id IN :recordIds WITH SYSTEM_MODE LIMIT 2000];
        }
    }
}
